$('#modal').addEventListener('click',e=>{let t=e.target,exampleIndex=t.dataset.exampleIndex;if(exampleIndex!==undefined){let field=$('#attitudeNote')||$('#batchAttitudeNote');if(field)field.value=attitudeExamples()[Number(exampleIndex)]||'';return}if(t.dataset.removeExample!==undefined){let index=Number(t.dataset.removeExample);attitudeExamples().splice(index,1);if(!attitudeExamples().length)attitudeExamples().push(...defaultAttitudeExamples);save();refreshExamplePickers();return}if(t.id==='addAttitudeExample'){let text=prompt('추가할 예시 문장을 입력하세요.');if(text?.trim()){attitudeExamples().push(text.trim());save();refreshExamplePickers()}return}if(t.id==='saveAttitude'){let student=cls().students.find(s=>s.id===t.dataset.student);if(student)setTimeout(()=>showRecordFeedback(student.name,score,student.id),0)}});
$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;if(mode==='attendance')attitudeBatch=null;$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));renderModeControls();$('#attitudeHint').hidden=true});
$('#attendanceControls').onclick=e=>{let button=e.target.closest('button');if(!button)return;if(button.dataset.attendanceSave!==undefined){ses().attendanceSaved=true;save();button.classList.add('is-saved');button.textContent='출결 저장됨 ✓';renderProgress();$('#syncText').textContent='출결이 저장됨';return}if(button.dataset.status){status=status===button.dataset.status?null:button.dataset.status;renderModeControls();return}let action=button.dataset.attitudeAction;if(!action)return;let setting={"all-plus":[1,true],plus:[1,false],zero:[0,false],minus:[-1,false],"all-minus":[-1,true]}[action];openAttitudeBatch(setting[0],setting[1])};
$('#attendanceControls').addEventListener('click',e=>{let button=e.target.closest('button'),action=button?.dataset.attitudeAction,point={plus:1,zero:0,minus:-1}[action];if(point!==undefined&&attitudeBatch&&attitudeBatch.score===point){e.stopImmediatePropagation();attitudeBatch=null;renderModeControls();$('#syncText').textContent='태도 점수 선택 해제'}},true);

document.addEventListener('click',e=>{if(e.target.closest('[data-progress-action]'))renderLessonForDate();let calendar=e.target.closest('[data-progress-calendar]');if(calendar){let input=calendar.parentElement.querySelector('[data-progress-date]');if(typeof input.showPicker==='function')input.showPicker();else input.click()}});
document.addEventListener('change',e=>{if(e.target.dataset.progressDate)renderLessonForDate()});
$('#modal').addEventListener('click',e=>{if(e.target.closest('.modal-close,[value="cancel"]')){e.preventDefault();closeModal()}});
$('#modal').addEventListener('click',e=>{if(e.target.closest('[data-score]'))e.preventDefault()});
$('#seatingGrid').addEventListener('click',e=>{let card=e.target.closest('.student-seat');if(mode==='attendance'&&card&&ses().deletedAttendance)delete ses().deletedAttendance[card.dataset.id]},true);
