// 현재는 JSON 텍스트 파일 저장을 기본으로 사용하며, Firebase 연결 메뉴는 필요할 때 사용할 수 있습니다.
$('#reportTable').onclick=e=>{let studentButton=e.target.closest('[data-delete-student-records]');if(studentButton){e.preventDefault();e.stopPropagation();let student=cls().students.find(item=>item.id===studentButton.dataset.deleteStudentRecords);if(!student||!confirm(`${student.name} 학생의 모든 출결·학습 태도 기록을 삭제할까요?`))return;deleteStudentRecords(student.id);save();render();$('#syncText').textContent='학생 기록을 전체 삭제함';return}let button=e.target.closest('[data-delete-record]');if(!button)return;let [type,date,studentId,recordedAt]=button.dataset.deleteRecord.split('|');if(!confirm('이 기록을 삭제할까요?'))return;let session=cls().sessions[date];if(type==='attitude')session.attitudes=(session.attitudes||[]).filter(item=>!(item.studentId===studentId&&String(item.createdAt)===recordedAt));else{session.deletedAttendance||={};session.deletedAttendance[studentId]=true}save();renderReport();$('#syncText').textContent='기록이 삭제됨'};
function showAuthModal(register=false){modal(`<div class="modal-body"><h2>${register?'교사 계정 만들기':'교사 로그인'}</h2><p>교사용 이메일과 비밀번호로 학급 데이터를 안전하게 관리합니다.</p><input id="authEmail" type="email" placeholder="이메일" autocomplete="email"><input id="authPassword" type="password" placeholder="비밀번호 (6자 이상)" autocomplete="current-password"><div class="modal-actions"><button type="button" id="authToggle" class="secondary-button">${register?'로그인으로':'계정 만들기'}</button><button type="button" id="authSubmit" data-register="${register}" class="primary-button">${register?'계정 만들기':'로그인'}</button></div></div>`)}
$('#firebaseButton').onclick=()=>{if(auth?.currentUser){if(confirm('로그아웃할까요?'))auth.signOut();return}showAuthModal()};
$('#modal').addEventListener('click',async e=>{let target=e.target;if(target.id==='authToggle')return showAuthModal(!($('#authSubmit').dataset.register==='true'));if(target.id!=='authSubmit')return;let email=$('#authEmail').value.trim(),password=$('#authPassword').value;if(!email||!password)return alert('이메일과 비밀번호를 입력해 주세요.');try{if(target.dataset.register==='true')await auth.createUserWithEmailAndPassword(email,password);else await auth.signInWithEmailAndPassword(email,password);$('#modal').close()}catch(error){alert(error.message)}});
render();

// Google 교사 계정별로 브라우저 데이터를 분리하고, 로그인 전에는 앱을 표시하지 않습니다.
const emptyTeacherState=()=>{let fresh=seed(),first=fresh.classes[0];first.name='새 학급';first.students=[];first.sessions={};first.progress={};return fresh};
const normalizeTeacherState=()=>{if(!state||!Array.isArray(state.classes)||!state.classes.length)state=emptyTeacherState();state.classes.forEach(c=>{c.layout={rows:6,cols:6,formation:'exam',...c.layout};c.layout.rows=6;c.layout.cols=6;c.sessions||={};c.progress||={};c.students||=[];c.students.forEach(s=>s.number=String(s.number||'').padStart(5,'0'))});if(!state.classes.some(c=>c.id===state.activeClass))state.activeClass=state.classes[0].id};
const teacherStorageKey=uid=>`attendanceBook:${uid}`;
const loadTeacherState=uid=>{try{state=JSON.parse(localStorage.getItem(teacherStorageKey(uid))||'null')||emptyTeacherState()}catch{state=emptyTeacherState()}normalizeTeacherState();progressDate=key;swap=null;render()};
function scheduleCloudSave(){cloudSavePending=true;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(async()=>{if(cloudSaveInProgress||!cloudReady||!auth?.currentUser)return;cloudSavePending=false;cloudSaveInProgress=true;try{await cloudSave()}catch(error){console.error('Firebase 자동 저장 실패',error);$('#syncText').textContent=`자동 저장 실패 (${syncErrorCode(error)})`}finally{cloudSaveInProgress=false;if(cloudSavePending)scheduleCloudSave()}},700)}
function stopCloudSync(){if(cloudUnsubscribe){cloudUnsubscribe();cloudUnsubscribe=null}clearTimeout(cloudRemoteSyncTimer);cloudRemoteSyncTimer=null}
function startCloudSync(user){stopCloudSync();cloudUnsubscribe=db.collection('classes').where('ownerId','==',user.uid).onSnapshot(()=>{if(!cloudReady||cloudSaveInProgress||cloudSavePending)return;clearTimeout(cloudRemoteSyncTimer);cloudRemoteSyncTimer=setTimeout(async()=>{if(!cloudReady||cloudSaveInProgress||cloudSavePending||auth?.currentUser?.uid!==user.uid)return;try{await cloudLoad(user);$('#syncText').textContent='다른 기기의 변경 사항을 반영함'}catch(error){console.error('Firebase 실시간 동기화 실패',error);$('#syncText').textContent=`실시간 동기화 실패 (${syncErrorCode(error)})`}},700)},error=>{$('#syncText').textContent=`실시간 동기화 연결 실패 (${syncErrorCode(error)})`})}
async function cloudLoad(user){let snapshot=await db.collection('classes').where('ownerId','==',user.uid).get(),remoteClasses=[];for(let classDoc of snapshot.docs){let data=classDoc.data();if(data.deletedAt)continue;let [studentsSnap,lessonsSnap,layoutSnap,settingsSnap]=await Promise.all([classDoc.ref.collection('students').get(),classDoc.ref.collection('lessons').get(),classDoc.ref.collection('layouts').doc('current').get(),classDoc.ref.collection('settings').doc('general').get()]);let students=studentsSnap.docs.map(doc=>({id:doc.data().id||doc.id,...doc.data()})).filter(student=>!student.deletedAt).map(student=>({id:student.id,number:String(student.number||'').padStart(5,'0'),name:student.name||'',seat:student.seat??null})),sessions={},progress={};lessonsSnap.docs.forEach(doc=>{let lesson=doc.data();if(lesson.deletedAt)return;let date=lesson.date||doc.id;sessions[date]={attendance:lesson.attendance||{},attitudes:lesson.attitudes||[],attendanceSaved:!!lesson.attendanceSaved,deletedAttendance:lesson.deletedAttendance||{}};if(lesson.classHour||lesson.period||lesson.content)progress[date]={classHour:lesson.classHour||'',period:lesson.period||'',content:lesson.content||''}});let layout=layoutSnap.exists?layoutSnap.data().layout:null;remoteClasses.push({id:classDoc.id,name:data.name||'이름 없는 학급',ownerId:data.ownerId||user.uid,layout:{rows:6,cols:6,formation:'exam',...(layout||{})},students,sessions,progress});if(settingsSnap.exists&&Array.isArray(settingsSnap.data().attitudeExamples))state.attitudeExamples=settingsSnap.data().attitudeExamples}if(remoteClasses.length){state={activeClass:remoteClasses[0].id,classes:remoteClasses,attitudeExamples:state.attitudeExamples};normalizeTeacherState();save(false);render(false)}if(!cloudUnsubscribe)startCloudSync(user);$('#syncText').textContent=remoteClasses.length?'웹 저장 정보를 불러옴':'새 교사 계정입니다'}
const authGate=document.createElement('section');authGate.className='auth-gate';authGate.innerHTML='<div class="auth-card"><div class="auth-mark">▦</div><h1>학급 출석부</h1><p>교사 Google 계정으로 로그인하면<br>본인의 학급 기록만 안전하게 관리할 수 있습니다.</p><button type="button" class="google-signin" data-google-login><span class="google-g">G</span>Google 계정으로 계속하기</button><p class="auth-note" data-auth-message>처음 로그인하면 교사 계정이 자동으로 만들어집니다.</p></div>';document.body.append(authGate);
const authMessage=text=>{let target=authGate.querySelector('[data-auth-message]');if(target)target.textContent=text};
const showAppForTeacher=profile=>{let isAdmin=!!profile.isAdmin;document.body.classList.remove('app-locked');authGate.hidden=true;$('#firebaseButton').textContent='로그아웃';$('#syncText').textContent=isAdmin?'관리자 교사로 로그인됨':'교사 로그인됨';adminNav.hidden=!isAdmin;if(!isAdmin&&$('#admin').classList.contains('active'))showView('dashboard')};
const showView=viewId=>{$$('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===viewId));$$('.view').forEach(view=>view.classList.toggle('active',view.id===viewId));$('.sidebar').classList.remove('open');if(viewId==='admin')renderAdminDashboard()};
const dashboardLayoutCard=$('#adminGrid').closest('.content-card');dashboardLayoutCard.classList.add('dashboard-layout-card');const dashboardPerspective=document.createElement('div');dashboardPerspective.className='perspective-switch dashboard-perspective-switch';dashboardPerspective.innerHTML='<button type="button" data-perspective="teacher" class="active">선생님 시점</button><button type="button" data-perspective="student">학생 시점</button>';$('#randomButton').before(dashboardPerspective);
const applyPerspective=next=>{perspective=next;let formation=dashboardLayoutCard.querySelector('.formation-options'),desk=dashboardLayoutCard.querySelector('.teacher-desk'),layoutGrid=$('#adminGrid'),saveLayout=$('#saveLayoutButton');dashboardLayoutCard.classList.toggle('dashboard-student-perspective',perspective==='student');if(perspective==='student')dashboardLayoutCard.append(formation,desk,layoutGrid,saveLayout);else dashboardLayoutCard.append(formation,layoutGrid,desk,saveLayout);$$('[data-perspective]').forEach(button=>button.classList.toggle('active',button.dataset.perspective===perspective));grid(layoutGrid,true);grid($('#seatingGrid'))};
$$('[data-perspective]').forEach(button=>button.onclick=()=>applyPerspective(button.dataset.perspective));
const adminNav=document.createElement('button');adminNav.className='nav-item admin-nav';adminNav.dataset.view='admin';adminNav.hidden=true;adminNav.innerHTML='<span>⚙</span> 관리자 대시보드';$('.sidebar nav').append(adminNav);adminNav.onclick=()=>showView('admin');
const adminView=document.createElement('section');adminView.id='admin';adminView.className='view';adminView.innerHTML='<div class="page-heading"><div><p class="eyebrow">관리자 대시보드</p><h1>교사 회원 관리</h1><p class="subcopy">등록된 교사의 소속·담당 과목과 관리자 권한을 관리합니다.</p></div></div><div class="content-card"><div class="card-header"><div><h2>교사 계정</h2><p>Google 로그인으로 만들어진 교사 계정입니다.</p></div><button type="button" id="refreshTeachers" class="secondary-button">새로고침</button></div><div id="adminTeacherList" class="admin-teacher-list"><p class="subcopy">교사 목록을 불러오는 중입니다.</p></div></div>';$('#records').after(adminView);
async function renderAdminDashboard(){let list=$('#adminTeacherList');if(!db||!auth?.currentUser){list.innerHTML='<p class="subcopy">로그인이 필요합니다.</p>';return}list.innerHTML='<p class="subcopy">교사 목록을 불러오는 중입니다.</p>';try{let snapshot=await db.collection('users').get(),teachers=snapshot.docs.map(doc=>({uid:doc.id,...doc.data()})).sort((a,b)=>(a.name||a.email||'').localeCompare(b.name||b.email||'','ko'));list.innerHTML=teachers.length?teachers.map(teacher=>`<article class="admin-teacher-row" data-teacher-uid="${teacher.uid}"><div class="admin-teacher-identity"><b>${esc(teacher.name||'이름 없음')}</b><span>${esc(teacher.email||'이메일 없음')}</span></div><input type="text" data-school value="${esc(teacher.school||'')}" placeholder="소속 학교"><input type="text" data-subject value="${esc(teacher.subject||'')}" placeholder="담당 과목"><label class="admin-role"><input type="checkbox" data-admin ${teacher.isAdmin?'checked':''}> 관리자</label><button type="button" class="admin-save" data-save-teacher>저장</button></article>`).join(''):'<p class="subcopy">등록된 교사 계정이 없습니다.</p>'}catch(error){list.innerHTML='<p class="subcopy">교사 목록을 불러오지 못했습니다. 관리자 권한을 확인해 주세요.</p>'}}
$('#refreshTeachers').onclick=renderAdminDashboard;
$('#adminTeacherList').onclick=async event=>{let button=event.target.closest('[data-save-teacher]');if(!button||!db||!auth?.currentUser)return;let row=button.closest('[data-teacher-uid]'),uid=row.dataset.teacherUid,school=row.querySelector('[data-school]').value.trim(),subject=row.querySelector('[data-subject]').value.trim(),isAdmin=row.querySelector('[data-admin]').checked;button.disabled=true;button.textContent='저장 중…';try{await db.collection('users').doc(uid).set({school,subject,isAdmin,updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});button.textContent='저장됨';if(uid===auth.currentUser.uid){adminNav.hidden=!isAdmin;if(!isAdmin)showView('dashboard')}setTimeout(()=>{if(button.isConnected){button.disabled=false;button.textContent='저장'}},900)}catch(error){button.disabled=false;button.textContent='저장';alert('교사 권한 저장에 실패했습니다.')}};
const signInWithGoogle=async()=>{if(!auth)return authMessage('Firebase 인증 연결을 확인해 주세요.');let button=authGate.querySelector('[data-google-login]');button.disabled=true;authMessage('Google 로그인 창을 여는 중입니다…');try{let provider=new firebase.auth.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});await auth.signInWithPopup(provider)}catch(error){button.disabled=false;authMessage(error.code==='auth/operation-not-allowed'?'Firebase 콘솔에서 Google 로그인 제공업체를 먼저 사용 설정해 주세요.':'로그인에 실패했습니다. 다시 시도해 주세요.')}};
authGate.addEventListener('click',event=>{if(event.target.closest('[data-google-login]'))signInWithGoogle()});
$('#firebaseButton').onclick=()=>{if(auth?.currentUser&&confirm('로그아웃할까요?'))auth.signOut();else if(!auth)authMessage('Firebase 인증 연결을 확인해 주세요.')};
if(auth)auth.onAuthStateChanged(async user=>{if(!user){activeTeacherUid=null;cloudReady=false;document.body.classList.add('app-locked');authGate.hidden=false;authMessage('Google 계정으로 로그인해 시작하세요.');$('#firebaseButton').textContent='교사 로그인';return}let uid=user.uid;try{let profileRef=db.collection('users').doc(uid),snapshot=await profileRef.get(),profile=snapshot.exists?snapshot.data():null;if(!profile){profile={uid,email:user.email||'',name:user.displayName||'',school:'',subject:'',isAdmin:false};await profileRef.set({...profile,createdAt:firebase.firestore.FieldValue.serverTimestamp(),updatedAt:firebase.firestore.FieldValue.serverTimestamp()})}if(auth.currentUser?.uid!==uid)return;activeTeacherUid=uid;cloudReady=false;loadTeacherState(uid);await cloudLoad(user);cloudReady=true;showAppForTeacher(profile)}catch(error){await auth.signOut();authMessage('교사 프로필을 준비하지 못했습니다. Firestore 규칙을 확인해 주세요.')}});
if(auth)auth.onAuthStateChanged(user=>{if(!user)stopCloudSync()});

// 과제 제출·외부활동 확인표: 학생별 행과 항목별 열을 추가해 간단히 완료 여부를 관리합니다.
const submissionNav=document.createElement('button');submissionNav.className='nav-item';submissionNav.dataset.view='submissions';submissionNav.innerHTML='<span>▤</span> 제출·활동 확인';$('.sidebar nav').append(submissionNav);
const submissionsView=document.createElement('section');submissionsView.id='submissions';submissionsView.className='view';$('#records').after(submissionsView);
const submissionTracker=(current=cls())=>current.submissionTracker||=( {columns:[],checks:{}} );
const submissionLabel=(column,checked)=>checked?(column.type==='activity'?'참석':'제출'):(column.type==='activity'?'미참석':'미제출');
function renderSubmissionTracker(){let root=$('#submissions');if(!root)return;let data=submissionTracker(),oldColumn=$('#submissionColumnFilter')?.value||data.columns[0]?.id||'',oldStatus=$('#submissionStatusFilter')?.value||'missing',keyword=$('#submissionKeyword')?.value.trim().toLowerCase()||'',column=data.columns.some(item=>item.id===oldColumn)?oldColumn:'',students=cls().students.slice().sort((a,b)=>a.number.localeCompare(b.number)).filter(student=>{let matchesKeyword=`${student.number} ${student.name}`.toLowerCase().includes(keyword),checked=column?!!data.checks?.[student.id]?.[column]:false;return matchesKeyword&&(!column||oldStatus==='all'||(oldStatus==='missing'&&!checked)||(oldStatus==='complete'&&checked))}),options=data.columns.map(item=>`<option value="${item.id}" ${item.id===column?'selected':''}>${esc(item.name)}</option>`).join(''),headers=data.columns.map(item=>`<th><span class="submission-column-name">${esc(item.name)}</span><small>${item.type==='activity'?'외부활동':'과제'}</small><button type="button" class="submission-column-delete" data-delete-submission-column="${item.id}" aria-label="${esc(item.name)} 삭제">×</button></th>`).join(''),rows=students.map(student=>{let cells=data.columns.map(item=>{let checked=!!data.checks?.[student.id]?.[item.id];return `<td><button type="button" class="submission-cell ${checked?'is-complete':''}" data-toggle-submission="${student.id}|${item.id}">${submissionLabel(item,checked)}</button></td>`}).join('');return `<tr><th><b>${esc(student.name)}</b><small>${esc(student.number)}</small></th>${cells}</tr>`}).join('');root.innerHTML=`<div class="page-heading submission-heading"><div><p class="eyebrow">제출·외부활동 확인</p><h1>학생 제출 여부 확인</h1><p class="subcopy">과제 또는 외부활동 열을 추가한 뒤, 학생별 제출·참석 여부를 한 번씩 눌러 확인하세요.</p></div><div class="submission-actions"><button type="button" class="secondary-button" data-add-submission-column="task">+ 과제 추가</button><button type="button" class="primary-button" data-add-submission-column="activity">+ 외부활동 추가</button></div></div><div class="content-card submission-card"><div class="submission-filters"><label>항목<select id="submissionColumnFilter"><option value="">전체 항목</option>${options}</select></label><label>상태<select id="submissionStatusFilter"><option value="missing" ${oldStatus==='missing'?'selected':''}>미제출·미참석만</option><option value="complete" ${oldStatus==='complete'?'selected':''}>제출·참석만</option><option value="all" ${oldStatus==='all'?'selected':''}>전체</option></select></label><label class="submission-search">검색<input id="submissionKeyword" type="search" value="${esc(keyword)}" placeholder="학번 또는 이름 검색"></label><b class="submission-count">${students.length}명</b></div>${data.columns.length?`<div class="submission-table-wrap"><table class="submission-table"><thead><tr><th>학생</th>${headers}</tr></thead><tbody>${rows||`<tr><td colspan="${data.columns.length+1}" class="submission-empty">조건에 맞는 학생이 없습니다.</td></tr>`}</tbody></table></div>`:'<div class="submission-empty-state"><b>첫 항목을 추가해 확인표를 시작하세요.</b><span>과제는 제출·미제출, 외부활동은 참석·미참석으로 표시됩니다.</span></div>'}</div>`}
function openSubmissionColumnModal(type){modal(`<div class="modal-body"><p class="modal-eyebrow">${type==='activity'?'EXTERNAL ACTIVITY':'ASSIGNMENT'}</p><h2>${type==='activity'?'외부활동':'과제'} 항목 추가</h2><p>${type==='activity'?'행사 또는 외부활동 이름을 입력하세요.':'확인할 과제 이름을 입력하세요.'}</p><label for="submissionColumnName">항목 이름</label><input id="submissionColumnName" placeholder="예: ${type==='activity'?'과학관 체험학습':'독서록 1차'}" autofocus><div class="modal-actions"><button value="cancel" class="secondary-button">취소</button><button type="button" id="createSubmissionColumn" data-submission-column-type="${type}" class="primary-button">추가</button></div></div>`) }
submissionNav.onclick=()=>showView('submissions');
submissionsView.addEventListener('click',event=>{let add=event.target.closest('[data-add-submission-column]');if(add)return openSubmissionColumnModal(add.dataset.addSubmissionColumn);let toggle=event.target.closest('[data-toggle-submission]');if(toggle){let [studentId,columnId]=toggle.dataset.toggleSubmission.split('|'),data=submissionTracker(),row=data.checks[studentId]||={};row[columnId]=!row[columnId];save();renderSubmissionTracker();return}let remove=event.target.closest('[data-delete-submission-column]');if(remove){let data=submissionTracker(),column=data.columns.find(item=>item.id===remove.dataset.deleteSubmissionColumn);if(!column||!confirm(`'${column.name}' 항목과 확인 상태를 삭제할까요?`))return;data.columns=data.columns.filter(item=>item.id!==column.id);Object.values(data.checks).forEach(row=>delete row[column.id]);save();renderSubmissionTracker()}});
submissionsView.addEventListener('input',event=>{if(event.target.id==='submissionKeyword')renderSubmissionTracker()});submissionsView.addEventListener('change',event=>{if(event.target.id==='submissionColumnFilter'||event.target.id==='submissionStatusFilter')renderSubmissionTracker()});
$('#modal').addEventListener('click',event=>{let button=event.target.closest('#createSubmissionColumn');if(!button)return;event.preventDefault();let name=$('#submissionColumnName').value.trim();if(!name)return;submissionTracker().columns.push({id:newId(),name,type:button.dataset.submissionColumnType});closeModal();save();renderSubmissionTracker()});
const baseRender=render;render=function(queueCloud=true){baseRender(queueCloud);renderSubmissionTracker()};
const baseCloudSave=cloudSave;cloudSave=async function(current=cls()){await baseCloudSave(current);if(!db||!auth?.currentUser||!current)return;let tracker=submissionTracker(current),classRef=db.collection('classes').doc(current.id),stamp=firebase.firestore.FieldValue.serverTimestamp();await classRef.collection('settings').doc('submissions').set({columns:tracker.columns,checks:tracker.checks,updatedAt:stamp},{merge:true});await classRef.set({submissionSyncAt:stamp,updatedAt:stamp},{merge:true})};
const baseCloudLoad=cloudLoad;cloudLoad=async function(user){let activeClass=state.activeClass;await baseCloudLoad(user);if(state.classes.some(current=>current.id===activeClass))state.activeClass=activeClass;if(!db||!auth?.currentUser||auth.currentUser.uid!==user.uid)return;await Promise.all(state.classes.filter(current=>current.ownerId===user.uid).map(async current=>{let snapshot=await db.collection('classes').doc(current.id).collection('settings').doc('submissions').get(),data=snapshot.exists?snapshot.data():{};current.submissionTracker={columns:Array.isArray(data.columns)?data.columns:[],checks:data.checks&&typeof data.checks==='object'?data.checks:{}}}));render(false)};
render(false);
